// View source embedded into the standalone prototype by build-state-atlas.mjs.
let atlasMode='journey',showAllTransitions=false,atlasZoom=1;
const capabilityGroups=[['运动执行',['session','algorithm','task']],['家庭管理',['binding','privacy','sync']],['反馈与扩展',['growth','analysis','posture','school']],['运行保障',['maintenance']]];
function setAtlasMode(m){atlasMode=m;atlasZoom=1;render()}
function selectDomain(id){domain=id;node=0;atlasMode='state';atlasZoom=1;render()}
function selectNode(i){const old=document.getElementById('atlas-canvas');const left=old?old.scrollLeft:0,top=old?old.scrollTop:0;node=i;render();const current=document.getElementById('atlas-canvas');if(current){current.scrollLeft=left;current.scrollTop=top}}
function toggleTransitions(){showAllTransitions=!showAllTransitions;atlasZoom=1;render()}
function graph(d){const src=atlasGraphs[d.id+(showAllTransitions?'_full':'_main')]||atlasGraphs.architecture;return src.replace('id="node_'+d.id+'_'+node+'" class="node atlas-node"','id="node_'+d.id+'_'+node+'" class="node atlas-node is-selected"')}
function getAtlasSVG(){if(atlasMode==='state')return graph(domains.find(d=>d.id===domain));return atlasGraphs[atlasMode]}
function zoomAtlas(delta){atlasZoom=Math.max(.5,Math.min(2,atlasZoom+delta));const svg=document.querySelector('#atlas-canvas svg');if(svg)svg.style.width=(Number(svg.dataset.naturalWidth)*atlasZoom)+'px';const label=document.getElementById('atlas-zoom');if(label)label.textContent=Math.round(atlasZoom*100)+'%'}
function canvasSVG(){const src=getAtlasSVG();const match=src.match(/viewBox="([^"]+)"/);const w=match?Number(match[1].split(/\s+/)[2]):1000;return src.replace('<svg ',`<svg data-natural-width="${w}" style="width:${w*atlasZoom}px;max-width:none;height:auto" `)}
function atlas(){const d=domains.find(x=>x.id===domain),s=d.states[node];const title={journey:'一次运动，四端怎样交接？',capability:'完整软件有哪些能力？',architecture:'谁负责什么，数据往哪里流？',state:d.title+' · 局部状态转移'}[atlasMode];const subtitle={journey:'从上到下读步骤，按泳道看责任。这里只画正常主链；异常进入局部状态图。',capability:'从左到右读包含关系。树枝表示分类，不代表执行顺序；点击能力进入对应状态图。',architecture:'概念架构：只显示主要职责与单向数据关系，部署方式与通信技术尚未冻结。',state:showAllTransitions?'显示当前模型全部候选转移。灰线为一般路径，橙色虚线为异常或返回；所有关系保留。':'先读正常路径。异常与恢复先列在下方，可切换查看全部候选转移。'}[atlasMode];const input=d.edges.filter(e=>e[1]===node),output=d.edges.filter(e=>e[0]===node);return `<div class="atlas-top"><div><span class="eyebrow">分层阅读 / 候选设计 / PM范围待确认</span><h2>${title}</h2><p class="muted">${subtitle}</p></div><div class="row">${btn('导出当前图 SVG','downloadGraph()')}${btn('场景推演 →',"changeView('play')",'primary')}</div></div><div class="row atlas-switch">${[['journey','1 运动泳道'],['capability','2 能力树'],['architecture','3 职责架构'],['state','4 局部状态']].map(([id,n])=>btn(n,`setAtlasMode('${id}')`,atlasMode===id?'active':'')).join('')}</div><div class="atlas-shell"><aside class="atlas-index"><h3>局部状态目录</h3>${capabilityGroups.map(([group,ids])=>`<div class="index-group"><small>${group}</small>${ids.map(id=>{const x=domains.find(d=>d.id===id);return btn(x.title,`selectDomain('${id}')`,atlasMode==='state'&&domain===id?'active':'')}).join('')}</div>`).join('')}<p class="muted">图形用于回答一个问题。账号、网络、授权、运动与上传各自建模，避免组合成一张巨图。</p></aside><section class="atlas-center"><div class="atlas-toolbar"><div class="row"><span class="legend-mark"></span><span>正常路径 / 职责关系</span>${atlasMode==='state'?'<span class="legend-mark exception"></span><span>异常 / 返回</span>':''}</div><div class="row">${atlasMode==='state'?btn(showAllTransitions?'查看正常主链':'展开全部转移','toggleTransitions()',showAllTransitions?'active':''):''}${btn('−',"zoomAtlas(-.1)")}<span id="atlas-zoom">${Math.round(atlasZoom*100)}%</span>${btn('+',"zoomAtlas(.1)")}</div></div><div class="atlas-canvas" id="atlas-canvas">${canvasSVG()}</div>${atlasMode==='state'?`<div class="state-inspector"><div><span class="tag">已选状态 ${s.id}</span><h3>${s.name}</h3><p>${s.note}</p></div><div><small>进入条件 / 触发</small><p>${input.map(e=>`${d.states[e[0]].name} → ${e[2]}`).join('<br>')||'起点或外部触发'}</p></div><div><small>允许退出</small><p>${output.map(e=>`${e[2]} → ${d.states[e[1]].name}`).join('<br>')||'终态或上层返回'}</p></div></div><div class="exception-strip"><h3>异常与恢复规则</h3><p>${d.rule}</p><small>待评审：${d.open}</small><p>图与模拟器共同用于讨论，部分节点尚无交互实现；图上出现不代表进入11/15交付范围。</p></div>`:atlasMode==='journey'?`<div class="reading-strip"><b>接下来检查异常</b><div class="row">${btn('离画 / 暂停恢复',"selectDomain('session')")}${btn('断网 / 结果补传',"selectDomain('sync')")}${btn('摄像头 / 授权关闭',"selectDomain('privacy')")}${btn('从场景跑一遍',"changeView('play')")}</div></div>`:`<div class="reading-strip"><b>${atlasMode==='capability'?'范围树保留完整设计；PM只裁本轮实现与验收。':'设备会话拥有实时计数；后台接收结果；家长查看最近确认状态。'}</b><p class="muted">图形节点可进入局部状态图。角色、技术与候选范围分别标明，不把架构箭头当作运动状态转移。</p></div>`}</section></div>`}
function downloadGraph(){const name=atlasMode==='state'?domains.find(d=>d.id===domain).title:({journey:'运动泳道',capability:'能力树',architecture:'职责架构'})[atlasMode];download('运动伙伴_'+name+'_候选图.svg',getAtlasSVG(),'image/svg+xml')}
